<script setup>
import { ref, watch } from 'vue';
import MButton from '../../../components/mds/MButton.vue';
import MEmptyState from '../../../components/mds/MEmptyState.vue';
import MInput from '../../../components/mds/MInput.vue';
import MTag from '../../../components/mds/MTag.vue';

const props = defineProps({ rows: { type: Array, default: () => [] }, total: { type: Number, default: 0 }, page: { type: Number, default: 1 }, pageSize: { type: Number, default: 20 }, search: { type: String, default: '' }, loading: { type: Boolean, default: false }, error: { type: String, default: '' } });
const emit = defineEmits(['search', 'page', 'open']); const query = ref(props.search);
watch(() => props.search, (value) => { query.value = value; });
function submitSearch() { emit('search', query.value.trim()); }
function score(value) { const number = Number(value); return Number.isFinite(number) ? `${number}/100` : '—'; }
</script>

<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><h1 class="text-[20px] font-semibold leading-7">Danh bạ nhân sự</h1><p class="mt-1 text-[13px] leading-[18px] text-[var(--mds-text-secondary)]">Tra cứu nhân sự theo dữ liệu đã được máy chủ projection theo PolicyEngine.</p><form class="mt-4 flex max-w-[560px] gap-2" @submit.prevent="submitSearch"><MInput v-model="query" placeholder="Tìm theo họ tên, cơ quan, chức vụ…" :disabled="loading" /><MButton variant="primary" :loading="loading" @click="submitSearch">Tìm</MButton></form></header><p v-if="error" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error }}</p><section class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><div class="flex items-center justify-between border-b border-[var(--mds-border-light)] px-5 py-3"><p class="text-[13px] text-[var(--mds-text-secondary)]">{{ total.toLocaleString('vi-VN') }} nhân sự</p><p class="text-[12px] text-[var(--mds-text-secondary)]">Trang {{ page }}</p></div><div v-if="rows.length" class="overflow-x-auto"><table class="w-full min-w-[760px] text-left"><thead class="bg-[var(--mds-bg-page)] text-[12px] font-medium text-[var(--mds-text-secondary)]"><tr><th class="px-5 py-3">Nhân sự</th><th class="px-3 py-3">Cơ quan</th><th class="px-3 py-3">Chức vụ</th><th class="px-3 py-3">Mảng</th><th class="px-3 py-3 text-right">Điểm quan hệ</th><th class="px-5 py-3"></th></tr></thead><tbody class="divide-y divide-[var(--mds-border-light)]"><tr v-for="person in rows" :key="person.id" class="hover:bg-[var(--mds-bg-page)]"><td class="px-5 py-3"><div class="flex items-center gap-3"><span class="grid h-9 w-9 place-items-center rounded-full bg-[var(--mds-brand-50)] text-[12px] font-semibold text-[var(--mds-brand-700)]">{{ person.initials }}</span><div><strong class="block text-[13px]">{{ person.name }}</strong><MTag v-if="person.status !== '—'" color="neutral" class="mt-1">{{ person.status }}</MTag></div></div></td><td class="px-3 py-3 text-[13px]">{{ person.orgName }}</td><td class="px-3 py-3 text-[13px]">{{ person.position !== '—' ? person.position : person.level }}</td><td class="px-3 py-3 text-[13px]">{{ person.beat }}</td><td class="px-3 py-3 text-right text-[13px] font-medium">{{ person.hasRelationshipScore ? score(person.relationshipScore) : '—' }}</td><td class="px-5 py-3 text-right"><MButton variant="link" @click="emit('open', person.id)">Mở hồ sơ</MButton></td></tr></tbody></table></div><MEmptyState v-else-if="!loading" title="Không tìm thấy nhân sự" description="Thử đổi từ khóa tìm kiếm hoặc xóa bộ lọc." /><div v-else class="px-5 py-8 text-center text-[13px] text-[var(--mds-text-secondary)]">Đang tải danh bạ…</div></section><footer class="flex justify-end gap-2"><MButton variant="neutral" :disabled="loading || page <= 1" @click="emit('page', page - 1)">Trang trước</MButton><MButton variant="neutral" :disabled="loading || page * pageSize >= total" @click="emit('page', page + 1)">Trang sau</MButton></footer></div></section></template>
